"use strict";(self.webpackChunkreact_portfolio=self.webpackChunkreact_portfolio||[]).push([[2859],{2859:function(i){i.exports=JSON.parse('{"name":"Patrick Goodwin","menu":{"home":"Casa","about":"Su di me","portfolio":"Portfolio","projects":"Progetti di siti web","tiger":"Linguaggio della tigre","portfolio_translator":"Traduttore di portfolio","formatter":"Formattatore JSON e YAML","contact":"Contattami"},"home":{"title":"Ingegnere full-stack senior | Prodotti e sistemi","animated":{"first":"Ingegnere full-stack senior","second":"Costruttore di sistemi e architettura","third":"Ingegnere di prodotto SaaS","fourth":"Software affidabile, risultati aziendali"},"footer":"Sito web ora tradotto e disponibile in oltre 100 lingue!","descriptionA":"Ingegnere full-stack senior con oltre 6 anni di esperienza nel trasformare prodotti da requisiti ambigui a sistemi di produzione affidabili. Progetto l\'architettura dietro le applicazioni React, Angular, .NET, Node.js, Java, C#, Go e SQL: confini chiari dei servizi, modelli di dati durevoli, modelli di accesso sicuri e percorsi di consegna che i team possono operare con sicurezza.","descriptionB":"Il mio lavoro collega le decisioni ingegneristiche ai risultati aziendali. Da un SaaS per la stima della costruzione che trasforma i dati dei fogli di calcolo in proposte pronte per il cliente a piattaforme web che generano entrate, creo software in base al flusso di lavoro, al rischio e valore misurabile che conta per le persone che lo utilizzano.","portfolio_button":"Il mio portafoglio","contact_button":"Contattami","about_button":"Su di me"},"about":{"title":"Su di me","personal_summary":{"title":"Riepilogo personale","text":"Sono un ingegnere full-stack senior con sede a Orlando, Florida, che segue il percorso dal problema del prodotto al risultato della produzione. Faccio scelte tecnologiche a servizio del sistema: .NET ed Entity Framework Core quando contano un dominio fortemente strutturato e una persistenza testabile; Angolare o Reagire quando complesso i flussi di lavoro necessitano di un\'interfaccia gestibile; Node.js o Go quando un\'API, un\'integrazione o uno strumento ad alte prestazioni necessita di un runtime mirato. Attraverso i prodotti SaaS, i flussi di lavoro interni e le piattaforme rivolte ai clienti, guido con compromessi espliciti, progettazione sicura e resiliente, test automatizzati e pratiche di consegna che aiutare i team a fornire software prezioso senza lasciare dietro di s\xe9 debiti operativi."},"professional_experience":{"title":"Esperienza professionale","entries":[{"jobtitle":"Ingegnere informatico senior","where":"Progettazione interattiva","date":"2025 - Presente"},{"jobtitle":"Ingegnere del software","where":"Assicurazione Orion180","date":"2024-2025"},{"jobtitle":"Ingegnere del software","where":"SupremeMC","date":"2020-2024"},{"jobtitle":"Ingegnere del software","where":"Accelera l\'apprendimento","date":"2023"},{"jobtitle":"Ingegnere software capo (programma per studenti)","where":"Programma GDI della Clemson University","date":"2021-2022"},{"jobtitle":"Supervisore alla scrivania","where":"Clemson University","date":"2021-2022"}]},"technical_skills":{"title":"Competenze tecniche","header1":"Linguaggi di programmazione","header2":"Framework e librerie","header3":"Strumenti e tecnologie"},"services":{"title":"I miei servizi","entries":[{"title":"Ingegneria dello stack completo","text":"Conduco la consegna del prodotto end-to-end: traduco i flussi di lavoro aziendali in confini del sistema, modelli di dati, API e interfacce, quindi svolgo il lavoro attraverso test, implementazione, e iterazione. L\'obiettivo \xe8 un software che un team possa evolvere e far funzionare, non una raccolta di schermi sconnessi."},{"title":"Architettura del prodotto e della piattaforma","text":"Scelgo piattaforme e modelli in base al problema: servizi .NET stratificati per domini aziendali, applicazioni Angular o React basate su componenti per operazioni complesse, applicazioni relazionali modelli di dati per flussi di lavoro responsabili e integrazioni progettati tenendo conto delle modalit\xe0 di errore, del controllo degli accessi e della manutenibilit\xe0."},{"title":"Consegna pronta per la produzione","text":"Costruisco tenendo in considerazione le realt\xe0 successive al lancio: segreti tenuti fuori dal controllo del codice sorgente, percorsi espliciti di migrazione del database, autorizzazione basata sui ruoli, convalida ai limiti del sistema, test automatizzati, consapevolezza CI/CD e osservabilit\xe0 pratica. Questi sono i dettagli che trasformano un prototipo in un software affidabile."}]}},"portfolio":{"title":"Portfolio","filter_by":"Filtra portafoglio per:","entries":{"biblioteca":{"title":"BibliotecaJSON","text":"Una pipeline di localizzazione basata su Python che trasforma un\'origine di contenuto strutturato in un portfolio accessibile a livello globale. Gestisce i dati di traduzione come un sistema gestibile anzich\xe9 come copie di pagine duplicate manualmente, consentendo al sito di adattarsi a oltre 100 lingue e rendendo la portata globale un capacit\xe0 operativa anzich\xe9 una funzionalit\xe0 una tantum.","link":"https://github.com/pattygcoding/Biblioteca-JSON"},"connect_four":{"title":"Collega quattro","text":"Vasta famiglia di oltre 50 implementazioni del gioco Connect Four. Questo progetto include implementazioni in oltre 30 diversi linguaggi di programmazione, tra cui Java, C++, Python, JavaScript e altri. Inoltre, include oltre 20+ framework diversi o altri formati, tra cui React.js, Ruby on Rails, ASP.NET e altro.","link":"https://github.com/pattygcoding/Connect-Four-Language-Tree"},"grocery_app":{"title":"App per la spesa","text":"Un\'applicazione .NET 9 Blazor Server full-stack che dimostra un\'architettura back-end intenzionale per un flusso di lavoro aziendale. La divisione controller/servizio/repository mantiene le regole dell\'applicazione, l\'accesso ai dati e la presentazione testabili in modo indipendente; Entity Framework Core fornisce persistenza duratura; e il una suite di test completa protegge il comportamento man mano che il prodotto si evolve.","link":"https://github.com/pattygcoding/Grocery-App-Blazor"},"interop":{"title":"Progetto di interoperabilit\xe0","text":"Un riferimento per l\'interoperabilit\xe0 tra linguaggi che abbraccia 15 linguaggi di programmazione e 18 modelli di esecuzione. Il progetto indaga il confine in cui i sistemi spesso diventano fragili: contratti di processo, scambio di dati, comportamento in fase di esecuzione e percorsi di integrazione ripetibili. Riflette il pensiero sistemico necessario quando un prodotto \xe8 pi\xf9 grande di una singola pila.","link":"https://github.com/pattygcoding/Interop-Samples"},"inventory_register":{"title":"Registro degli inventari","text":"Un flusso di lavoro POS e inventario full-stack creato con Angular 17+ e Node.js. Modella le preoccupazioni operative di un sistema B2B: utenti autenticati, controllo degli accessi basato sui ruoli, accuratezza dell\'inventario e un flusso di pagamento fittizio. Il progetto \xe8 concepito in base al lavoro effettivo svolto da un team di registrazione, non solo a un catalogo di funzionalit\xe0 della struttura.","link":"https://github.com/pattygcoding/Restaurant-Inventory-Register"},"formatter":{"title":"Formattazione automatica JSON e YAML","text":"Uno strumento di convalida e formattazione JSON e YAML basato su browser integrato in Go e compilato in WebAssembly. Lo spostamento del motore di analisi in WASM mantiene l\'interazione reattiva e locale al browser applicando al contempo un vero parser per rilevare input non validi. \xc8 un esempio mirato di scelta di un\'architettura runtime per prestazioni, portabilit\xe0 e fiducia degli utenti.","link":"https://github.com/pattygcoding/JSON-YAML-Auto-Formatter"},"takeoff_engine":{"title":"Motore di decollo","text":"Una stima della costruzione SaaS costruita attorno a un flusso di lavoro dell\'appaltatore costoso e soggetto a errori. Il prodotto React + Express acquisisce dati CSV ed Excel, mappa colonne incoerenti in un modello di dominio utilizzabile, calcola i volumi di scavo di trincee e movimenti di terra, tiene traccia della manodopera e markup e produce proposte PDF e Word pronte per il cliente. Si tratta dell\'ingegneria dell\'intero ciclo di vita del prodotto: analisi dei dati, regole di calcolo, un flusso di lavoro raffinato dell\'operatore e risultati finali che aiutano un\'azienda a passare dagli input grezzi a un\'offerta.","link":"https://takeoffengine.com"},"minecraft_json_generator":{"title":"Generatore JSON di Minecraft","text":"Generatore JSON leggero integrato in Python per pacchetti di risorse e dati Minecraft. Questo progetto viene utilizzato per generare file JSON per le mod di Minecraft, inclusi elementi, blocchi ed entit\xe0 personalizzati. Molto utile non solo per creare pacchetti dati personalizzati, ma anche per le mod tramite la funzione di cambio del nome della mod.","link":"https://github.com/pattygcoding/Minecraft-JSON-Generator"},"educational_experience":{"title":"La mia esperienza educativa","text":"Accanto ai miei progetti personali, ho acquisito numerose competenze anche attraverso esperienze formative. Clicca qui per visualizzare il mio profilo LinkedIn per ulteriori informazioni.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"professional_experience":{"title":"La mia esperienza professionale","text":"Oltre sei anni di esperienza ingegneristica professionale in team di prodotto, piattaforme aziendali e software rivolti ai clienti. Il mio lavoro ha incluso la creazione di livelli applicativi mantenibili, la collaborazione tra discipline di distribuzione e la presa di decisioni tecniche relative al ciclo di vita del prodotto, alle rischio e propriet\xe0 a lungo termine in vista.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"portfolio_website":{"title":"Sito web del portafoglio di Patrick Goodwin","text":"Un portafoglio React orientato alla produzione che tratta l\'accessibilit\xe0 e la portata globale come requisiti ingegneristici. Include una pipeline di traduzione gestibile per oltre 100 lingue, strumenti interattivi supportati da WebAssembly, modelli di interfaccia utente reattivi e accessibili e un\'architettura di progetto progettato per crescere man mano che viene spedito nuovo lavoro.","link":"https://www.pattygcoding.com"},"lua_library":{"title":"Libreria di script Lua di Patrick","text":"Un\'utile libreria di script Lua per riferimento futuro. Questa libreria viene utilizzata per automatizzare le attivit\xe0 negli script Lua, che possono tornare utili per attivit\xe0 che richiedono prestazioni, poich\xe9 Lua \xe8 solitamente un linguaggio di scripting pi\xf9 veloce sia di Python che di Ruby.","link":"https://github.com/pattygcoding/Lua-Scripts"},"excel_scripts":{"title":"Script per fogli di calcolo Microsoft Excel di Patrick (VBA)","text":"Un\'utile libreria di script VBA per Microsoft Excel. Questa libreria viene utilizzata per automatizzare le attivit\xe0 nei fogli di calcolo Excel.","link":"https://github.com/pattygcoding/Spreadsheet-Scripts"},"neovim_config":{"title":"Configurazione Neovim di Patrick","text":"La mia personale configurazione Neovim. Questo progetto viene utilizzato per configurare Neovim a mio piacimento, incluse combinazioni di tasti, temi e plugin personalizzati. Questo progetto viene utilizzato per rendere Neovim pi\xf9 facile da usare ed efficiente per il mio uso personale.","link":"https://github.com/pattygcoding/Neovim-Config"},"python_maps":{"title":"Generatore di mappe di Patrick","text":"Uno strumento di reporting geospaziale Python creato con GeoPandas e Matplotlib per generare mappe di contee e stati degli Stati Uniti. Trasforma i dati geografici in artefatti di analisi leggibili, dimostrando una mentalit\xe0 di pipeline di dati: selezionare le giuste librerie di dominio, normalizzare gli input e produrre output che sostenere decisioni chiare.","link":"https://i.imgur.com/HxYLSXC.png"},"powershell_library":{"title":"Libreria di script PowerShell di Patrick","text":"Un\'utile libreria di script PowerShell per riferimento futuro. Utile con la funzionalit\xe0 di script $profile, lo trovo estremamente utile per automatizzare le attivit\xe0 dal terminale Windows, poich\xe9 sono un utente frequente del sistema operativo Windows.","link":"https://github.com/pattygcoding/Powershell-Scripts"},"ruby_library":{"title":"Libreria di script Ruby di Patrick","text":"Un\'utile libreria di script Ruby per riferimento futuro. Utile per futuri concetti di sviluppo di Ruby on Rails.","link":"https://github.com/pattygcoding/Ruby-Scripts"},"pdf_builder":{"title":"PDF Costruttore di competenze","text":"Un flusso di lavoro di generazione di documenti creato con dati Python, Pdfkit, Jinja2, HTML e JSON strutturati. Separa i dati riutilizzabili dai modelli di presentazione per generare in modo coerente curriculum PDF personalizzati, un modello pratico per ridurre il lavoro manuale e creare documenti aziendali ripetibile.","link":"https://github.com/pattygcoding/PDFBuilderPublic"},"rijandel_encryption":{"title":"Progetto di crittografia Rijandel","text":"Un set comparativo di oltre 10 implementazioni Rijndael nelle varianti a 128, 192 e 256 bit. Reimplementare un algoritmo sensibile alla sicurezza tra le lingue \xe8 un esercizio disciplinato di specifiche esatte, comportamento testabile e limiti della portabilit\xe0 a livello di lingua, tutti istinti utili per i sistemi che gestiscono dati sensibili.","link":"https://github.com/pattygcoding/SupremeMC"},"suprememc":{"title":"SupremeMC Minecraft Mod","text":"Una mod di Minecraft che aggiunge strumenti personalizzati, armature, mob, blocchi, dimensioni e molte altre funzionalit\xe0 al gioco. Costruito con le versioni Java 8-17 per versioni selezionate di Minecraft tra 1.16 e 1.20.","link":"https://www.curseforge.com/minecraft/mc-mods/suprememc"},"tiger_programming_language":{"title":"Linguaggio di programmazione Tiger","text":"Un linguaggio di programmazione e un interprete personalizzati integrati in Go per esplorare la progettazione del runtime del linguaggio, il comportamento di esecuzione e i compromessi in termini di prestazioni. Compilarlo in WebAssembly e integrarlo nel portfolio crea una superficie di prodotto reale e ispezionabile per l\'ingegneria a livello di sistema anzich\xe9 lasciare il lavoro come un esperimento solo sul repository.","link":"https://www.pattygcoding.com/tiger"},"tiger_tailgating_pros":{"title":"Sito web dei professionisti di Tiger Tailgating","text":"Un sito Web React consegnato per un\'azienda di tailgating di Clemson, Carolina del Sud. Il lavoro traduce l\'offerta di una piccola impresa in un chiaro percorso del cliente e in una presenza web affidabile, applicando il pensiero del prodotto per aiutare una vera organizzazione a convertire l\'interesse in richieste e entrate.","link":"https://github.com/pattygcoding/TTProsBeta"},"turing_machine":{"title":"Progetto della macchina di Turing","text":"Famiglia di oltre 30+ implementazioni della Macchina di Turing. Utilizzato per dimostrare la completezza del turing per diversi linguaggi di programmazione per la ricerca, in particolare per il linguaggio di programmazione Tiger.","link":"https://github.com/pattygcoding/Turing-Machines"}}},"tiger_programming_language":{"title":"Linguaggio di programmazione Tiger"},"contact":{"title":"Contattami","header":"Informazioni sui contatti","email":"pattygsocials@gmail.com","description":"Rispondo alle richieste provenienti da e-mail e messaggi LinkedIn. Richiamer\xf2 anche se il mio numero viene fornito tramite curriculum o in altro modo, anche se preferisco mantenere privato il mio numero di telefono."},"formatter":{"title":"Linter JSON e YAML","description":"Uno strumento di qualit\xe0 dei dati basato su browser che convalida e formatta JSON e YAML utilizzando un motore Go compilato in WebAssembly. L\'architettura continua l\'analisi vicino all\'utente per un feedback rapido e privato, applicando al tempo stesso regole di sintassi reali al confine dei dati. \xc8 un esempio compatto di progettazione di un flusso di lavoro di sviluppo affidabile basato su correttezza, prestazioni e fiducia.","more_info1":"Per maggiori informazioni consultare il file README nel","more_info2":"Repository del formattatore JSON/YAML.","format_as":"Formato come:","auto_detect":"Rilevamento automatico","format":"Lanugine e formato","valid_json":"\u2713 JSON valido","valid_yaml":"\u2713 YAML valido","invalid_json":"JSON non valido","invalid_yaml":"YAML non valido","empty_input":"Inserisci un po\' di JSON o YAML per lint.","too_large":"Ingresso troppo grande (max 1 MB consentito).","fixed_yaml_spacing":"\u26a0 YAML presentava spaziatura/rientro non validi ma \xe8 stato corretto e formattato automaticamente.","loading":"Caricamento formattatore...","waiting_for_input":"In attesa di input...","load_failed":"Impossibile caricare il formattatore.","output":"Produzione:","input_code":"Ingresso","json_examples":"Esempi JSON","yaml_examples":"Esempi YAML"},"tiger":{"title":"Linguaggio della tigre","description":"Tiger \xe8 un linguaggio di programmazione personalizzato e un interprete Go creato per esplorare l\'architettura di runtime, la semantica del linguaggio e i compromessi in termini di prestazioni. La compilazione dell\'interprete in WebAssembly trasforma il funzionamento dei sistemi in un prodotto interattivo basato su browser: gli utenti possono eseguire i programmi direttamente mentre il runtime rimane portabile e isolato dall\'applicazione host.","more_info1":"Per maggiori informazioni consultare il file README nel","more_info2":"Repository GitHub del linguaggio di programmazione Tiger.","select_engine":"Seleziona motore:","tiger_code":"Codice tigre:","run_tiger":"Corri Tigre","output":"Produzione:"},"tab":{"title":"Patrick Goodwin","description":"Ingegnere full-stack senior con oltre 6 anni di esperienza nella progettazione di prodotti SaaS, sistemi di produzione e software che generano entrate."},"copy":{"text":"Copia","copied":"Copiato!"},"social_media":{"github":"GitHub","linkedin":"LinkedIn","youtube":"YouTube","text_strip":"Seguimi"},"languages":{"title":"Traduttore di portfolio","description":"Scopri come il mio portfolio \xe8 accessibile ai visitatori di tutto il mondo con il supporto di oltre 100 lingue.","global_accessibility":{"title":"Accessibilit\xe0 globale","description":"Il mio portfolio \xe8 disponibile in oltre {count} lingue, rendendolo accessibile ai visitatori di tutto il mondo. Questo approccio multilingue dimostra il mio impegno per l\'inclusivit\xe0 e la portata globale nello sviluppo di software.","stats":{"languages_supported":"Lingue supportate","countries_represented":"Paesi rappresentati","continents_covered":"Continenti coperti"}},"features":{"title":"Caratteristiche","items":[{"title":"Traduzione in tempo reale:","description":"Cambia lingua istantaneamente con il selettore della lingua"},{"title":"Lingua basata su URL:","description":"Le preferenze della lingua vengono conservate nell\'URL"},{"title":"Supporto script nativi:","description":"Rendering corretto di script come arabo, cinese, hindi e altro"},{"title":"Sensibilit\xe0 culturale:","description":"Le traduzioni considerano il contesto culturale, non solo i significati letterali"},{"title":"Ottimizzato per il SEO:","description":"Ogni variante linguistica \xe8 ottimizzata per i motori di ricerca"}]},"world_map":{"title":"Mappa del mondo interattiva","description":"Passa il mouse sopra i paesi sulla mappa per vedere le lingue supportate:","languages_label":"Lingue","legend":{"supported":"Lingue supportate","not_supported":"Nessun supporto linguistico"},"zoom_controls":{"zoom_in":"Ingrandisci","zoom_out":"Rimpicciolisci","reset":"Reimposta vista"}},"supported_languages":{"title":"Lingue supportate"},"interactive_country_map":{"title":"Mappa interattiva del paese","description":"Passa il mouse sopra i paesi qui sotto per vedere le lingue supportate:","language_count":{"single":"lingua","multiple":"lingue"}},"tooltips":{"no_language_support":"Nessun supporto linguistico"}},"logotext":"PATRIZIO"}')}}]);